def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]
    opp_c = 0
    recent_opp_c = 0
    recent_my_d = 0
    start = n - 10 if n > 10 else 0
    for i in range(n):
        a, b = history[i]
        if b == 'C':
            opp_c += 1
        if i >= start:
            if b == 'C':
                recent_opp_c += 1
            if a == 'D':
                recent_my_d += 1
    opp_d = n - opp_c
    recent_len = n - start
    recent_opp_d = recent_len - recent_opp_c

    if n == 90:
        if opp_c == n and last_my == 'C' and last_opp == 'C' and rng.random() < 0.2:
            return 'D'
    if n == 91:
        if opp_c == n and last_my == 'D' and last_opp == 'C':
            return 'C'
    if n == 92:
        if opp_c == n and last_my == 'C' and last_opp == 'C' and history[-2] == ('D', 'C'):
            return 'C'
    if n == 93:
        if (
            opp_c == n and last_my == 'C' and last_opp == 'C'
            and history[-3] == ('D', 'C') and history[-2] == ('C', 'C')
        ):
            return 'D'
    if n >= 94:
        if opp_c == n and last_my == 'D':
            return 'D'

    if last_opp == 'D':
        if last_my == 'D':
            if recent_opp_d <= 1 and opp_c * 3 >= n * 2:
                return 'C'
            return 'D'
        if recent_my_d > 0 and recent_opp_d <= 2:
            if opp_c * 3 >= n * 2 or (opp_c > 0 and opp_d <= 3):
                return 'C'
        return 'D'

    return 'C'
